#define SIZE 1024
int matrix[SIZE][SIZE];
long accumulator = 0;

// Optimal Spatial Locality: Row-Major Traversal (Sequential access)
for (int i = 0; i < SIZE; i++) {
    for (int j = 0; j < SIZE; j++) {
        accumulator += matrix[i][j];
    }
}

#define SIZE 1024
int matrix[SIZE][SIZE];
long accumulator = 0;

// Poor Spatial Locality: Column-Major Traversal (Large strides/Cache misses)
for (int j = 0; j < SIZE; j++) {
    for (int i = 0; i < SIZE; i++) {
        // Jumps (i * SIZE) memory locations for each inner loop iteration
        accumulator += matrix[i][j];
    }
}

// Data Structure Layout (Array of Structs): Good spatial locality for related fields
struct Vector3 {
    float x, y, z; // Stored adjacently
};

Vector3 vertices[100];

// Accessing x, y, z for vertices[i] pulls all data into the cache simultaneously
for (int i = 0; i < 100; ++i) {
    vertices[i].x += 1.0f;
    vertices[i].y *= 2.0f;
}
